import re
from datetime import datetime

_ANGLE_RE = re.compile(r"<([^<>]*)>")
_ZIP_PLUS4_RE = re.compile(r"^[0-9]{4,5}-[0-9]{4}$")
_UPDATED_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_DIGITS = "0123456789"
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}


def _is_ascii_digits(s):
    return bool(s) and all(c in _DIGITS for c in s)


def _norm_email(raw):
    """Return the normalized email, or "" if it is not valid."""
    s = (raw or "").strip()
    m = _ANGLE_RE.search(s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") != 1:
        return ""
    local, domain = s.split("@")
    if domain in _GMAIL_DOMAINS:
        local = local.replace(".", "").split("+", 1)[0]
        domain = "gmail.com"
    if not local or "." not in domain or domain.startswith(".") or domain.endswith("."):
        return ""
    return f"{local}@{domain}"


def _norm_phone(raw):
    """Return the normalized 10-digit phone, or "" if it is not valid."""
    s = (raw or "").lower()
    cut = len(s)
    for marker in ("ext", "x", "#"):
        i = s.find(marker)
        if i != -1 and i < cut:
            cut = i
    digits = "".join(c for c in s[:cut] if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    if len(digits) == 10 and digits[0] not in "01":
        return digits
    return ""


def _norm_zip(raw):
    s = (raw or "").strip()
    if _ZIP_PLUS4_RE.match(s):
        s = s.split("-")[0]
    if len(s) == 4 and _is_ascii_digits(s):
        s = "0" + s
    if len(s) == 5 and _is_ascii_digits(s):
        return s
    return ""


def _norm_name(raw):
    s = (raw or "").strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_updated(raw):
    s = (raw or "").strip()
    for fmt in _UPDATED_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def _norm_tags(raw):
    return {t.strip().lower() for t in re.split(r"[;,]", raw or "") if t.strip()}


def dedupe_contacts(rows):
    # Step 1: normalize rows and drop those with no valid email or phone.
    recs = []
    for idx, row in enumerate(rows):
        def g(key):
            return row.get(key) or ""

        email = _norm_email(g("email"))
        phone = _norm_phone(g("phone"))
        if not email and not phone:
            continue
        recs.append({
            "idx": idx,
            "first_name": _norm_name(g("first_name")),
            "last_name": _norm_name(g("last_name")),
            "zip": _norm_zip(g("zip")),
            "email": email,
            "phone": phone,
            "source": g("source").strip().lower(),
            "tags": _norm_tags(g("tags")),
            "opted_out": g("opted_out").strip().lower() in _OPT_OUT_VALUES,
            "updated": _parse_updated(row.get("updated")),
        })

    # Step 2: union-find so matching is transitive.
    parent = list(range(len(recs)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[max(ra, rb)] = min(ra, rb)

    by_email = {}
    by_phone_last = {}
    for pos, rec in enumerate(recs):
        if rec["email"]:
            if rec["email"] in by_email:
                union(by_email[rec["email"]], pos)
            else:
                by_email[rec["email"]] = pos
        if rec["phone"] and rec["last_name"]:
            key = (rec["phone"], rec["last_name"].lower())
            if key in by_phone_last:
                union(by_phone_last[key], pos)
            else:
                by_phone_last[key] = pos

    groups = {}
    for pos in range(len(recs)):
        groups.setdefault(find(pos), []).append(pos)
    # recs is in input order, so members are sorted by input position.
    ordered = sorted(groups.values(), key=lambda members: members[0])

    # Step 3: pick the representative values for each person.
    def pick(members, field):
        cands = [recs[p] for p in members if recs[p][field]]
        if not cands:
            return ""
        # Stable sorts applied in reverse priority order:
        # earliest input row, then latest updated, then manual first.
        cands.sort(key=lambda r: r["idx"])
        cands.sort(key=lambda r: r["updated"], reverse=True)
        cands.sort(key=lambda r: r["source"] != "manual")
        return cands[0][field]

    result = []
    for members in ordered:
        tags = set()
        for p in members:
            tags |= recs[p]["tags"]
        result.append({
            "first_name": pick(members, "first_name"),
            "last_name": pick(members, "last_name"),
            "zip": pick(members, "zip"),
            "email": pick(members, "email"),
            "phone": pick(members, "phone"),
            "source": pick(members, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(recs[p]["opted_out"] for p in members) else "N",
            "updated": max(recs[p]["updated"] for p in members).strftime("%Y-%m-%d"),
        })
    return result
